def len(list):
    lengths = [0,0,0,0]
    for s in list:
        if s == "A":
            lengths[0] += 1
        elif s =="C":
            lengths[1] +=1
        elif s =="G":
            lengths[2] += 1
        else:
            lengths[3] +=1
    return lengths


print("Hello, World!")
x = ""
letters =list(x)
result =len(letters)
print(result)




        



